"use client";

import Image from "next/image";
import { useSearchParams, useRouter } from "next/navigation";
import { useCategories } from "@/hooks/useCategories";
import Pagination from "@/components/products/Pagination";
import SkeletonRow from "@/app/dashboard/admin/categories/SkeletonRow";

const CategoryTable = () => {
  const searchParams = useSearchParams();
  const router = useRouter();

  // Get page & search query from URL
  const currentPage = Number(searchParams.get("page")) || 1;
  const searchQuery = searchParams.get("search") || "";
  const pageSize = 10;

  // Update URL when filters change
  const updateQueryParams = (newParams: { page?: number; search?: string }) => {
    const params = new URLSearchParams(searchParams);
    
    if (newParams.page !== undefined) params.set("page", String(newParams.page));
    if (newParams.search !== undefined) params.set("search", newParams.search);

    router.push(`/dashboard/admin/categories?${params.toString()}`);
  };

  const { data, isLoading, isError } = useCategories(currentPage, pageSize, searchQuery);

  if (isError) return <p>Failed to load categories.</p>;

  return (
    <div>
      {/* Search Bar */}
      <input
        type="text"
        placeholder="Search categories..."
        value={searchQuery}
        onChange={(e) => updateQueryParams({ search: e.target.value, page: 1 })}
        className="border p-2 mb-4"
      />

      <table className="border-collapse border border-gray-300 w-full">
        <thead>
          <tr className="bg-gray-200">
            <th className="border p-2 text-gray-400">Category Picture</th>
            <th className="border p-2 text-gray-400">Category Name</th>
          </tr>
        </thead>
        <tbody>
          {isLoading
            ? Array.from({ length: 10 }).map((_, index) => <SkeletonRow key={index} />)
            : data?.content?.map((category) => (
                <tr key={category.categoryId}>
                  <td className="border p-2 text-gray-400">
                    <div className="w-[50px] h-[50px] flex items-center justify-center overflow-hidden rounded">
                      <Image
                        src={category.categoryPicture}
                        alt={category.categoryName}
                        width={50}
                        height={50}
                        className="rounded object-cover"
                        unoptimized
                      />
                    </div>
                  </td>
                  <td className="border p-2 text-gray-400">{category.categoryName}</td>
                </tr>
              ))}
        </tbody>
      </table>

      {/* Pagination */}
      {!isLoading && data && (
        <Pagination
          currentPage={currentPage}
          totalPages={data.totalPages || 1}
          setCurrentPage={(page) => updateQueryParams({ page })}
        />
      )}
    </div>
  );
};

export default CategoryTable;